using System.Collections.Generic;
using FluentAssertions;
using GrowthBook.Providers;
using Microsoft.Extensions.Logging.Abstractions;
using Newtonsoft.Json.Linq;
using Xunit;

namespace GrowthBook.Tests.CustomTests;

/// <summary>
/// Version operators treat a missing, null, empty, boolean or array attribute as version 0, as in the reference SDK.
/// Expected values were generated by running each case through the JS SDK's evalCondition.
/// </summary>
public class VersionConditionTests
{
    private readonly ConditionEvaluationProvider _provider = new(new NullLogger<ConditionEvaluationProvider>());

    [Theory]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":null}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":\"\"}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":true}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":false}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":[1,2]}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":1}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":1.5}", false)]
    [InlineData("{\"v\":{\"$veq\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":null}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":\"\"}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":true}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":false}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":[1,2]}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":1}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":1.5}", true)]
    [InlineData("{\"v\":{\"$vne\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", false)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":null}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":\"\"}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":true}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":false}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":[1,2]}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":1}", true)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":1.5}", false)]
    [InlineData("{\"v\":{\"$vlt\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":null}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":\"\"}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":true}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":false}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":[1,2]}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":1}", false)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":1.5}", true)]
    [InlineData("{\"v\":{\"$vgt\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", false)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":null}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":\"\"}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":true}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":false}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":[1,2]}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":1}", true)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":1.5}", false)]
    [InlineData("{\"v\":{\"$vlte\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", true)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":null}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":\"\"}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":true}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":false}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":[1,2]}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":1}", false)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":1.5}", true)]
    [InlineData("{\"v\":{\"$vgte\":\"1.0.0\"}}", "{\"v\":\"1.0.0\"}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":null}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":\"\"}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":true}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":false}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":[1,2]}", true)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":1}", false)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":1.5}", false)]
    [InlineData("{\"v\":{\"$veq\":\"0\"}}", "{\"v\":\"1.0.0\"}", false)]
    public void EvalCondition_VersionOperator_MatchesJavaScript(string condition, string attributes, bool expected)
    {
        _provider.EvalCondition(JObject.Parse(attributes), JObject.Parse(condition)).Should().Be(expected);
    }

    [Fact]
    public void EvalFeature_VersionRuleOnMissingAttribute_ContinuesToLaterRules()
    {
        var features = new Dictionary<string, Feature>
        {
            ["f"] = new Feature
            {
                DefaultValue = "default",
                Rules = new List<FeatureRule>
                {
                    new() { Condition = JObject.Parse(@"{ ""version"": { ""$vgt"": ""1.0.0"" } }"), Force = "first" },
                    new() { Force = "second" }
                }
            }
        };

        var growthBook = new GrowthBook(new Context { Features = features, Attributes = JObject.Parse(@"{ ""id"": ""u1"" }") });

        var result = growthBook.EvalFeature("f");

        result.Value.ToString().Should().Be("second");
        result.Source.Should().Be(FeatureResult.SourceId.Force);
    }

    [Fact]
    public void Run_VersionConditionOnMissingAttribute_ReturnsNotInExperiment()
    {
        var growthBook = new GrowthBook(new Context { Attributes = JObject.Parse(@"{ ""id"": ""u1"" }") });

        var result = growthBook.Run(new Experiment
        {
            Key = "exp",
            Variations = new JArray(0, 1),
            Condition = JObject.Parse(@"{ ""version"": { ""$vgt"": ""1.0.0"" } }")
        });

        result.Should().NotBeNull();
        result.InExperiment.Should().BeFalse();
        result.Value.ToObject<int>().Should().Be(0);
    }
}
